def draw(seed):
    keys = jax.random.split(jax.random.key(seed), 4)
    return jax.vmap(lambda k: jax.random.normal(k, (2,)))(keys)
assert draw(7).shape == (4, 2)
assert jnp.array_equal(draw(7), draw(7))

